begin;
set local role postgres;
set local search_path = public, extensions;create extension if not exists pgtap with schema extensions;select plan(11);select has_table('public','passage_qa_versions','QA is versioned');select has_table('public','passage_qa_results','Passage QA results persist');select has_column('public','passage_qa_results','analysis_snapshot','Analysis is reproducible');select has_column('public','passage_qa_results','hard_failures','Hard failures remain explicit');select has_column('public','passage_qa_results','gate_results','Gate outcomes remain separate');select has_column('public','passage_qa_results','evaluator_provider','Independent provider is stamped');select has_column('public','passage_qa_results','evaluator_model','Independent model is stamped');select has_table('public','passage_qa_check_results','Atomic rule evidence persists');select has_column('public','passage_qa_check_results','hard_failure','Rules distinguish blocking failures');select col_is_unique('public','passage_qa_results',array['candidate_id','qa_version_id'],'One result per candidate and QA version');select col_is_unique('public','passage_qa_check_results',array['qa_result_id','gate','rule_key'],'One atomic result per rule');select * from finish();rollback;
